#pragma once

#include <cstddef>
#include <cstdint>
#include <string>

// Finds the game addresses a plugin needs, so it survives game updates (recipes generated by tools/siggen.py,
// table by tools/sigs2h.py). Per address, in order:
//   cached  - the address from the cache file, if it was made for this exe and these recipes, still passes its check
//   known   - the address of the build the recipes were made from, if it passes its check
//   found   - searched: the function's own pattern, its vtable slot, or references from other functions; every
//             anchor that hits must agree (two different answers = conflict = not found)
// A check is the cheapest proof the address is right: the prologue pattern, the RTTI name of a vtable, the slot
// content, or the first reference anchor at its known site decoding to the address.
// A function with no unique pattern has a fingerprint (`check`: its first bytes, not unique): whatever an anchor points
// at must have it, so a slot or a reference that lands on another function gives "not found" instead of a wrong address.
namespace resolver {

enum class Kind : std::uint8_t { Func, Thunk, Data, Vtable };
enum class AltKind : std::uint8_t { Ref, Within };

struct Alt {
    AltKind kind;
    const char* pattern;      // IDA style, "??" = any byte
    std::uint16_t site;       // ref: instruction offset in the pattern
    std::uint8_t operand;     // operand (rel32/disp32) offset in the instruction
    std::uint8_t end;         // instruction length (target = instruction + end + operand value)
    std::int16_t fn;          // within: recipe index of the function to look in
    std::uint16_t nth;        // within: which match inside that function
    std::uint32_t known_site; // rva of the instruction in the known build
};

struct Recipe {
    const char* name;
    Kind kind;
    std::uint32_t known;  // rva in the known build
    const char* pattern;  // func: unique prologue pattern, or nullptr
    const char* rtti;     // vtable: MSVC type name
    std::int16_t slot_vt; // slot: recipe index of the vtable, or -1
    std::int16_t slot;
    const Alt* alts;
    std::uint8_t nalts;
    const char* check;    // func without a pattern: fingerprint of its start, or nullptr
};

enum class How : std::uint8_t { Missing, Cached, Known, Found, Conflict };

struct Result {
    std::uint64_t rva = 0;
    How how = How::Missing;
    std::uint8_t hit = 0, total = 0; // anchors that agreed / tried (searched only)
    std::int16_t slot = -1;          // slot recipes: the vtable slot the function is in now (-1: not in it)
};

const char* how_name(How h);

// Resolves all recipes into out[n]. cache_path: read before, rewritten when anything had to be searched or the cache
// was missing / stale (nullptr = no cache). ignore_known: test mode, skips cache and known addresses (search only).
// Returns the number of addresses resolved.
std::size_t resolve(const Recipe* recipes, std::size_t n, Result* out, const wchar_t* cache_path, bool ignore_known);

// Struct offsets read from the game's code: each anchor is the nth match of a pattern within a witness function
// (recipe index) whose displacement (1 or 4 bytes at disp_at) holds the offset.
struct OffAnchor {
    std::int16_t fn;
    const char* pattern;
    std::uint16_t nth;
    std::uint8_t disp_at, disp_size;
};

struct Offset {
    const char* name;
    std::uint32_t known;
    const OffAnchor* anchors;
    std::uint8_t nanchors;
};

enum class OffsetStatus : std::uint8_t {
    Same,      // the game's code agrees with the known value
    Moved,     // at least two witnesses agree on a new value (out has it)
    Doubtful,  // witnesses contradict the known value but not enough to take theirs (out keeps the known one)
    Unchecked, // no witness found (out keeps the known one)
};

// out[i] = the offset to use: what the anchors that hit agree on when it equals the known value or at least two
// agree on a new one; the known value otherwise (logged). status (optional) says which. fns: the resolved recipes the
// anchors refer to. Returns the number of offsets that moved.
std::size_t resolve_offsets(const Offset* offsets, std::size_t n, const Result* fns, std::uint64_t* out,
                            OffsetStatus* status = nullptr);

// Tests only: resolve against an exe mapped with LoadLibraryExW(LOAD_LIBRARY_AS_IMAGE_RESOURCE) (its HMODULE without
// the low tag bits) instead of the running game.
void set_test_image(std::uint64_t base);

}
